#!/usr/bin/env python3
"""Autorenwerkzeug: Philipperbrief – Befunde, Deutungen, Grundsätze, Anwendungen, offene Fragen, Beziehungen,
Hintergrund zu Abschnitten, Kapitel-Zusammenfassungen, Kontext und Studie; jeweils mit Züridüütsch-Lokalisierung.
Hintergrund zum ganzen Buch steht in BG-PHP-BOOK-0001/-0002 (scripts/authoring/hintergrund_buecher.py) und wird hier
nicht geschrieben.

Abschnitte: Jede Aussage nennt den Versbereich, auf den sie sich bezieht; zugeordnet wird die kleinste vorhandene
Texteinheit (data/text-units/TU-PHP-…), die ihn ganz enthält, sonst die Kapiteleinheit.
Wortzählungen: nach den MACULA-Lemmata zum SBLGNT (data/annotations/MACULA-SBLGNT-PHP-00n.json).

Aufruf: python3 scripts/authoring/philipper_study.py
KI-Entwurf (Claude) vom 2026-10-13 auf Wunsch von Andi Neck; keine fachliche Prüfung erfolgt.
"""
import re
import sys
import pathlib

sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent))
from _lib import D  # noqa: E402

TAGS = ["TAG-PHILIPPIANS"]
CHAPTERS = {1: "TU-PHP-001-001-030", 2: "TU-PHP-002-001-030", 3: "TU-PHP-003-001-021", 4: "TU-PHP-004-001-023"}
_UNITS = sorted(p.stem for p in (D / "text-units").rglob("TU-PHP-*.json"))


def U(ch, v1, v2=None):
    """Kleinste vorhandene Texteinheit, die Kapitel ch, Verse v1–v2 ganz enthält; sonst die Kapiteleinheit."""
    v2 = v2 or v1
    best = None
    for uid in _UNITS:
        m = re.fullmatch(r"TU-PHP-(\d{3})-(\d{3})-(\d{3})", uid)
        if m and int(m[1]) == ch and int(m[2]) <= v1 and int(m[3]) >= v2:
            if best is None or int(m[3]) - int(m[2]) < best[0]:
                best = (int(m[3]) - int(m[2]), uid)
    return best[1] if best else CHAPTERS[ch]


